\set ON_ERROR_STOP on
BEGIN;
SET LOCAL search_path=erp,pg_catalog;
CREATE FUNCTION pg_temp.assert_true(value boolean,message text) RETURNS void LANGUAGE plpgsql AS $$BEGIN IF value IS NOT TRUE THEN RAISE EXCEPTION 'ASSERT: %',message;END IF;END$$;
INSERT INTO erp.companies(id,code,name) VALUES('TENANT-M220-A','M220A','M220 A'),('TENANT-M220-B','M220B','M220 B');
INSERT INTO auth.users(id,role,email) VALUES
 ('22000000-0000-4000-8000-000000000001','authenticated','admin@m220.test'),('22000000-0000-4000-8000-000000000002','authenticated','denied@m220.test'),('22000000-0000-4000-8000-000000000003','authenticated','inactive@m220.test'),
 ('22000000-0000-4000-8000-000000000010','authenticated','one@m220.test'),('22000000-0000-4000-8000-000000000011','authenticated','two@m220.test'),('22000000-0000-4000-8000-000000000012','authenticated','three@m220.test'),('22000000-0000-4000-8000-000000000013','authenticated','four@m220.test');
INSERT INTO erp.users(id,username,display_name,email,status,company_id) VALUES
 ('22000000-0000-4000-8000-000000000001','admin','Admin','admin@m220.test','active','TENANT-M220-A'),('22000000-0000-4000-8000-000000000002','denied','Denied','denied@m220.test','active','TENANT-M220-A'),('22000000-0000-4000-8000-000000000003','inactive','Inactive','inactive@m220.test','inactive','TENANT-M220-A');
INSERT INTO erp.user_roles(user_id,role_id) SELECT '22000000-0000-4000-8000-000000000001',id FROM erp.app_roles WHERE code='system-administrator';
INSERT INTO erp.operators(id,name,status,company_id) VALUES('M220-OP-A','Operator A','Active','TENANT-M220-A'),('M220-OP-B','Operator B','Active','TENANT-M220-B');

SELECT pg_temp.assert_true((erp.command_provision_application_user('{"actorId":"22000000-0000-4000-8000-000000000002","companyId":"TENANT-M220-A","authUserId":"22000000-0000-4000-8000-000000000010","commandId":"denied","idempotencyKey":"denied","username":"denied-new","displayName":"Denied","email":"one@m220.test","roleCodes":["rental-operations"]}'::jsonb)->>'code')='FORBIDDEN','missing permission denied');
SELECT pg_temp.assert_true((erp.command_provision_application_user('{"actorId":"22000000-0000-4000-8000-000000000003","companyId":"TENANT-M220-A","authUserId":"22000000-0000-4000-8000-000000000010","commandId":"inactive","idempotencyKey":"inactive","username":"inactive-new","displayName":"Inactive","email":"one@m220.test","roleCodes":["rental-operations"]}'::jsonb)->>'code')='FORBIDDEN','inactive denied');
SELECT pg_temp.assert_true((erp.command_provision_application_user('{"actorId":"22000000-0000-4000-8000-000000000001","companyId":"TENANT-M220-A","authUserId":"22000000-0000-4000-8000-000000000010","commandId":"bad-op","idempotencyKey":"bad-op","username":"bad-op","displayName":"Bad Op","email":"one@m220.test","roleCodes":["rental-operations"],"operatorId":"M220-OP-B"}'::jsonb)->>'success')='false','cross tenant operator denied');
SELECT pg_temp.assert_true((erp.command_provision_application_user('{"actorId":"22000000-0000-4000-8000-000000000001","companyId":"TENANT-M220-A","authUserId":"22000000-0000-4000-8000-000000000010","commandId":"bad-role","idempotencyKey":"bad-role","username":"bad-role","displayName":"Bad Role","email":"one@m220.test","roleCodes":["unknown"]}'::jsonb)->>'code')='INVALID_ROLE','unknown role denied');
SELECT pg_temp.assert_true((erp.command_provision_application_user('{"actorId":"22000000-0000-4000-8000-000000000001","companyId":"TENANT-M220-A","authUserId":"22000000-0000-4000-8000-000000000010","commandId":"bad-shape","idempotencyKey":"bad-shape","username":"bad-shape","displayName":"Bad Shape","email":"one@m220.test","roleCodes":"operator"}'::jsonb)->>'code')='INVALID_COMMAND','malformed roles denied');

CREATE TEMP TABLE result AS SELECT erp.command_provision_application_user('{"actorId":"22000000-0000-4000-8000-000000000001","companyId":"TENANT-M220-A","authUserId":"22000000-0000-4000-8000-000000000010","commandId":"valid","idempotencyKey":"valid","username":"operator-one","displayName":"Operator One","email":"one@m220.test","roleCodes":["finance","system-administrator","finance"]}'::jsonb) AS result_value;
SELECT pg_temp.assert_true((SELECT result_value->>'success'='true' FROM result),'authorized succeeds');
SELECT pg_temp.assert_true((SELECT count(*)=1 FROM erp.users WHERE id='22000000-0000-4000-8000-000000000010'),'one user');
SELECT pg_temp.assert_true((SELECT count(*)=2 FROM erp.user_roles WHERE user_id='22000000-0000-4000-8000-000000000010'),'roles exactly once');
SELECT pg_temp.assert_true((SELECT count(*)=1 FROM erp.audit_log WHERE aggregate_id='22000000-0000-4000-8000-000000000010' AND action='USER_CREATED'),'created audit once');
SELECT pg_temp.assert_true((SELECT count(*)=2 FROM erp.audit_log WHERE aggregate_id='22000000-0000-4000-8000-000000000010' AND action='USER_ROLE_ASSIGNED'),'role audits once');
SELECT pg_temp.assert_true((erp.command_provision_application_user('{"actorId":"22000000-0000-4000-8000-000000000001","companyId":"TENANT-M220-A","authUserId":"22000000-0000-4000-8000-000000000010","commandId":"valid","idempotencyKey":"valid","username":"operator-one","displayName":"Operator One","email":"one@m220.test","roleCodes":["finance","system-administrator","finance"]}'::jsonb)->>'replayed')='true','same replay');
SELECT pg_temp.assert_true((erp.command_provision_application_user('{"actorId":"22000000-0000-4000-8000-000000000001","companyId":"TENANT-M220-A","authUserId":"22000000-0000-4000-8000-000000000011","commandId":"changed","idempotencyKey":"valid","username":"changed","displayName":"Changed","email":"two@m220.test","roleCodes":["finance"]}'::jsonb)->>'code')='IDEMPOTENCY_MISMATCH','different replay rejected');
SELECT pg_temp.assert_true((erp.command_provision_application_user('{"actorId":"22000000-0000-4000-8000-000000000001","companyId":"TENANT-M220-A","authUserId":"22000000-0000-4000-8000-000000000011","commandId":"du","idempotencyKey":"du","username":"OPERATOR-ONE","displayName":"Duplicate","email":"two@m220.test","roleCodes":["finance"]}'::jsonb)->>'code')='USERNAME_CONFLICT','username conflict');
SELECT pg_temp.assert_true((erp.command_provision_application_user('{"actorId":"22000000-0000-4000-8000-000000000001","companyId":"TENANT-M220-A","authUserId":"22000000-0000-4000-8000-000000000011","commandId":"de","idempotencyKey":"de","username":"other","displayName":"Duplicate","email":"ONE@M220.TEST","roleCodes":["finance"]}'::jsonb)->>'code')='EMAIL_CONFLICT','email conflict');
SELECT pg_temp.assert_true(NOT EXISTS(SELECT 1 FROM erp.users WHERE id IN('22000000-0000-4000-8000-000000000011','22000000-0000-4000-8000-000000000012')),'failed commands leave no users');
SELECT pg_temp.assert_true((erp.record_application_user_password_reset('{"actorId":"22000000-0000-4000-8000-000000000001","companyId":"TENANT-M220-A","targetUserId":"22000000-0000-4000-8000-000000000010","commandId":"reset"}'::jsonb)->>'success')='true','reset audit succeeds');
SELECT pg_temp.assert_true((erp.record_application_user_password_reset('{"actorId":"22000000-0000-4000-8000-000000000002","companyId":"TENANT-M220-A","targetUserId":"22000000-0000-4000-8000-000000000010","commandId":"reset-denied"}'::jsonb)->>'code')='FORBIDDEN','reset denied');
SELECT pg_temp.assert_true(NOT EXISTS(SELECT 1 FROM erp.audit_log WHERE aggregate_id='22000000-0000-4000-8000-000000000010' AND (coalesce(new_values::text,'')||coalesce(metadata::text,''))~*'password|secret'),'no password audit');
SELECT pg_temp.assert_true(has_function_privilege('service_role','erp.command_provision_application_user(jsonb)','EXECUTE'),'service execute');
SELECT pg_temp.assert_true(NOT has_function_privilege('authenticated','erp.command_provision_application_user(jsonb)','EXECUTE') AND NOT has_function_privilege('anon','erp.command_provision_application_user(jsonb)','EXECUTE'),'browser denied');
ROLLBACK;
SELECT 'MILESTONE_220_DATABASE_CERTIFICATION_PASS';
